```verilog
`timescale 1ns/1ps

module tb;

    // 1. Declare inputs as regs, outputs as wires
    reg  [1023:0] in;
    reg  [7:0]    sel;
    wire [3:0]    out;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .in  (in),
        .sel (sel),
        .out (out)
    );

    // 3. Stimulus & self-checking:
    integer errors = 0;
    integer i;
    reg [3:0] expected_out;

    initial begin
        // Initialize inputs
        in  = 1024'h0;
        sel = 8'h0;
        #10;

        // Drive a known pattern into 'in'
        // We will assign a repeating 4-bit pattern or a shifting pattern
        for (i = 0; i < 256; i = i + 1) begin
            in[i*4 +: 4] = i[3:0];
        end

        // Test a subset of select values (0 to 255)
        // To keep it concise yet comprehensive, we can test boundary cases and a step of values.
        // Let's test selected indices: 0, 1, 2, 10, 15, 64, 127, 200, 255.
        // Or loop through all 256 since a 256-iteration loop is very fast in simulation.
        for (i = 0; i < 256; i = i + 1) begin
            sel = i[7:0];
            #5; // Wait for propagation

            expected_out = i[3:0];

            if (out !== expected_out) begin
                $display("ERROR: sel = %0d, expected out = 0x%h, got out = 0x%h", i, expected_out, out);
                errors = errors + 1;
            end
        end

        // Test with a different bit pattern in 'in'
        in = 1024'hFEDCBA9876543210FEDCBA9876543210FEDCBA9876543210FEDCBA9876543210; // filled with some pattern
        // Let's just create a procedural test for a few specific sel values
        sel = 8'd0;  #5;
        if (out !== in[3:0]) begin errors = errors + 1; end

        sel = 8'd1;  #5;
        if (out !== in[7:4]) begin errors = errors + 1; end

        sel = 8'd255;#5;
        if (out !== in[1023:1020]) begin errors = errors + 1; end

        // Final result check
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
```

